#!/bin/bash
set -euo pipefail
mkdir -p /opt/house-build/pdf-ocr-20260930 /opt/house-backups /opt/house-pdf-canary-data
cd /opt/house-build/pdf-ocr-20260930
base64 -d > ocr-route.ts <<'OCR_PAYLOAD'

OCR_PAYLOAD
base64 -d > docker-entrypoint.sh <<'ENTRY_PAYLOAD'

ENTRY_PAYLOAD
cat > Dockerfile <<'DOCKERFILE'
FROM house-app:20260930-miniapi
COPY ocr-route.ts /app/app/api/miniprogram/ocr/route.ts
COPY docker-entrypoint.sh /usr/local/bin/house-entrypoint
RUN chmod +x /usr/local/bin/house-entrypoint && cd /app && npm run build
DOCKERFILE
docker build -t house-app:20260930-pdfpaged . > build.log 2>&1 || { tail -60 build.log; exit 1; }
docker run --rm --entrypoint sh house-app:20260930-pdfpaged -c 'test ! -e /app/dist/server/.dev.vars'
docker run -d --name house-app-pdf-canary --network house-internal --env-file /opt/house-secrets/house-miniapi.env -v /opt/house-pdf-canary-data:/data house-app:20260930-pdfpaged >/dev/null
canary_ip=$(docker inspect -f '{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}' house-app-pdf-canary)
canary_ok=0
for attempt in $(seq 1 30); do if curl -fsS -o /dev/null "http://$canary_ip:3000/"; then canary_ok=1; break; fi; sleep 1; done
if [ "$canary_ok" -ne 1 ]; then docker logs --tail 40 house-app-pdf-canary; exit 1; fi
docker exec house-app-pdf-canary sh -c 'test -s /app/dist/server/.dev.vars && test "$(stat -c %a /app/dist/server/.dev.vars)" = 600'
docker rm -f house-app-pdf-canary >/dev/null
tar -czf /opt/house-backups/house-data-20260930-before-pdf.tar.gz -C /opt/house-data .
docker stop house-app >/dev/null
docker rename house-app house-app-before-pdf-0930
if ! docker run -d --name house-app --network house-internal --env-file /opt/house-secrets/house-miniapi.env --volumes-from house-app-before-pdf-0930 --restart unless-stopped house-app:20260930-pdfpaged >/dev/null; then
  docker rename house-app-before-pdf-0930 house-app
  docker start house-app >/dev/null
  exit 1
fi
production_ip=$(docker inspect -f '{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}' house-app)
production_ok=0
for attempt in $(seq 1 30); do if curl -fsS -o /dev/null "http://$production_ip:3000/"; then production_ok=1; break; fi; sleep 1; done
if [ "$production_ok" -ne 1 ]; then
  docker rm -f house-app >/dev/null
  docker rename house-app-before-pdf-0930 house-app
  docker start house-app >/dev/null
  echo 'New container failed health check; old container restored'
  exit 1
fi
printf 'DEPLOY_OK image=house-app:20260930-pdfpaged backup=/opt/house-backups/house-data-20260930-before-pdf.tar.gz\n'
